document.addEventListener("DOMContentLoaded",function(){const textBlocks=document.querySelectorAll(".content-section-scroll-txt .content-section-txt-inner");const imageBlocks=document.querySelectorAll(".content-section-scroll-img .content-section-img-inner");if(!textBlocks.length||textBlocks.length!==imageBlocks.length){console.warn("Scroll-sectie: aantal tekst- en beeldblokken komt niet overeen.");return;}
function setActive(index){imageBlocks.forEach((img,i)=>{img.classList.toggle("is-active",i===index);});textBlocks.forEach((txt,i)=>{const isCurrent=i===index;txt.classList.toggle("is-active",isCurrent);txt.classList.toggle("is-inactive",!isCurrent);txt.classList.toggle("is-done",i<index);});imageBlocks.forEach((img,i)=>{img.classList.toggle("is-done",i<index);});}
function updateActiveByCenter(){const viewportCenter=window.innerHeight/2;let closestIndex=0;let smallestDistance=Infinity;textBlocks.forEach((block,index)=>{const rect=block.getBoundingClientRect();const blockCenter=rect.top+rect.height/2;const distance=Math.abs(blockCenter-viewportCenter);if(distance<smallestDistance){smallestDistance=distance;closestIndex=index;}});setActive(closestIndex);}
let ticking=false;function requestUpdate(){if(ticking)return;ticking=true;window.requestAnimationFrame(()=>{updateActiveByCenter();ticking=false;});}
window.addEventListener("scroll",requestUpdate,{passive:true});window.addEventListener("resize",requestUpdate);updateActiveByCenter();});;